window.__DICT_CHUNKS__=window.__DICT_CHUNKS__||{};window.__DICT_CHUNKS__["K"]={"3891":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ka‧ra‧te</span><span class=\"meta-item\"><strong>IPA:</strong> /kəˈrɑːti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a Japanese fighting sport, in which you use your feet and hands to hit and kick → judo</div></div>","3892":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /kiːn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[want something]</strong> <em>especially British English</em> wanting to do something or wanting something to happen very much <em>SYN eager</em></div><ul class=\"examples\"><li><strong><em>keen to do something</strong>: He told me that he was keen to help.</em></li><li><strong><em>keen on doing something</strong>: I wasn’t keen on going there on my own.</em></li><li><strong><em>keen for something to happen</strong>: The government is keen for peace talks to start again.</em></li><li><strong><em>keen that</strong>: The chairman is keen that the company should expand its product range.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[like]</strong> <strong>be keen on somebody/something</strong> <em>British English</em> <em>spoken</em> to like someone or something:</div><ul class=\"examples\"><li><em>I’m not keen on cabbage.</em></li><li><strong><em>not too/not very/not that keen on something</strong>: She likes Biology, but she’s not too keen on Physics.</em></li><li><em>My flatmates want to have a party, but I’m not keen on the idea.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[hobby/interest]</strong> <em>especially British English</em> someone who is keen on something is very interested in it or enjoys doing it very much:</div><ul class=\"examples\"><li><em>a keen photographer</em></li><li><em>keen golfers</em></li><li><strong><em>keen on</strong>: Daniel’s very keen on tennis.</em></li><li><strong><em>mad keen on something</strong> (=very keen on something)</em>spoken<em>: I was mad keen on dinosaurs when I was little.</em></li><li><em>She takes a keen interest in politics and current affairs.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[eager to work/learn]</strong> someone who is keen is eager to work or learn, and enjoys doing it:</div><ul class=\"examples\"><li><em>keen students</em></li><li><em>The kids in my class are all very keen.</em></li><li><em>She was new in the job and keen as mustard (=very keen).</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[sight/smell/hearing]</strong> a keen sense of smell or keen sight or hearing is an extremely good ability to smell etc:</div><ul class=\"examples\"><li><em>Dogs have a very keen sense of smell.</em></li><li><em>She has a keen eye for (=is good at noticing) talent.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[mind]</strong> someone with a keen mind is quick to understand things:</div><ul class=\"examples\"><li><em>a keen understanding of commerce</em></li><li><em>With her keen mind and good business sense, she soon became noticed.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[feeling]</strong> a keen feeling is one that is strong and deep:</div><ul class=\"examples\"><li><em>As she walked away, Joe felt a keen sense of loss.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[competition]</strong> used to describe a situation in which people compete strongly:</div><ul class=\"examples\"><li><em>We won the contest in the face of keen competition.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[attracted]</strong> <strong>be keen on somebody</strong> <em>British English</em> to be sexually attracted to someone</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>[sharp]</strong> <em>literary</em> a keen knife or blade is extremely sharp</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>[wind]</strong> <em>old-fashioned</em> a keen wind is cold and strong</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>[prices]</strong> <em>British English</em> keen prices are low</div></div>","3893":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /kiːp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense and past participle kept /kept/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[not change]</strong> <span class=\"gram\">[linking verb, transitive]</span> to stay in a particular state, condition, or position, or to make someone or something do this GRAMMAR: Linking verbsKeep is used as a linking verb in this meaning. It links the subject of the sentence with an adjective: · I try to keep busy.· The fruit will keep fresh for several weeks.</div><ul class=\"examples\"><li><strong><em>keep (somebody/something) warm/safe/dry etc</strong>: We huddled around the fire to keep warm.</em></li><li><strong><em>keep calm/awake/sane etc</strong>: I was struggling to keep awake.</em></li><li><strong><em>keep something clean/tidy</strong>: Keep your room tidy.</em></li><li><strong><em>keep somebody busy/amused/occupied</strong>: some toys to keep the kids amused</em></li><li><em>You won’t be able to keep it secret forever.</em></li><li><em>Peter cycles to work to keep fit.</em></li><li><em>Don’t keep us in suspense any longer!</em></li><li><strong><em>keep (somebody/something) away/back/off/out etc</strong>: The police put up barriers to keep the crowds back. / If I were you, I’d keep away from that area at night. / a sign saying ‘Danger: Keep Out’ / The little boy kept close to his mother.</em></li><li><strong><em>keep (somebody) out of something</strong>: Keep him out of trouble. / You keep out of this, Mother (=do not get involved). It’s no concern of yours.</em></li><li><em>How can I cut your hair if you won’t keep still!</em></li><li><strong><em>keep left/right</strong> (=stay to the left or right of a path or road as you move)</em></li><li><strong><em>keep somebody/something doing something</strong>: Jane kept the engine running.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[continue doing something]</strong> <span class=\"gram\">[intransitive]</span> (also keep on) to continue doing something or to do the same thing many times GRAMMARKeep is followed by an -ing form, not an infinitive. You say: · He kept talking to me. ✗Don’t say: He kept to talk to me.Grammar guide ‒ VERBS</div><ul class=\"examples\"><li><strong><em>keep (on) doing something</strong>: I keep thinking about Joe, all alone in that place. / I keep telling you, but you won’t listen! / She pretended not to hear, and kept on walking.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[not give back]</strong> <span class=\"gram\">[transitive]</span> to have something and not give it back to the person who had it before:</div><ul class=\"examples\"><li><em>You can keep it. I don’t need it anymore.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[not lose]</strong> <span class=\"gram\">[transitive]</span> to continue to have something and not lose it or get rid of it:</div><ul class=\"examples\"><li><em>We decided to keep our old car instead of selling it.</em></li><li><em>I kept his letters for years.</em></li><li><em>In spite of everything, Robyn’s managed to keep her sense of humor.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[store something]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to leave something in one particular place so that you can find it easily:</div><ul class=\"examples\"><li><em>Where do you keep your teabags?</em></li><li><em>George kept a bottle of whiskey under his bed.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[make somebody stay in a place]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to make someone stay in a place, especially a prison or hospital:</div><ul class=\"examples\"><li><em>He was kept in prison for a week without charge.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[delay somebody]</strong> <span class=\"gram\">[transitive]</span> to delay someone:</div><ul class=\"examples\"><li><em>He should be here by now. What’s keeping him?</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[do what you promised]</strong> <span class=\"gram\">[transitive]</span> to do what you have promised or agreed to do</div><ul class=\"examples\"><li><strong><em>keep your word/promise</strong>: How do I know you’ll keep your word?</em></li><li><em>patients who fail to keep their appointments</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>keep a secret</strong> to not tell anyone about a secret that you know:</div><ul class=\"examples\"><li><em>Can I trust you to keep a secret?</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>keep something quiet/keep quiet (about something)</strong> to not say anything in order to avoid telling a secret or causing problems</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>keep a record/account/diary etc</strong> to regularly record written information somewhere</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>keep going</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <strong>keep (somebody) going</strong> to have or to give someone enough hope and emotional strength to continue living and doing things in a bad situation:</div><ul class=\"examples\"><li><em>That woman’s been through such a lot – I don’t know how she keeps going.</em></li><li><em>Her letters were the only thing that kept me going while I was in prison.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <strong>keep (something) going</strong> if you keep a business, institution, regular event etc going, you keep it open or make it continue to happen:</div><ul class=\"examples\"><li><em>The library costs £5 million a year to run, and the council can’t afford to keep it going.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> <strong>keep going</strong> to continue doing something difficult:</div><ul class=\"examples\"><li><em>Persevere and keep going until you reach your ideal weight.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">d)</span> <strong>keep somebody going</strong> if something keeps you going, it is enough to satisfy your need while you are waiting to get something bigger or better:</div><ul class=\"examples\"><li><em>I’ll have a biscuit to keep me going until dinner time.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[food]</strong> <span class=\"gram\">[intransitive]</span> if food keeps, it stays fresh enough to be eaten:</div><ul class=\"examples\"><li><em>Eat the salmon because it won’t keep till tomorrow.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>[animals]</strong> <span class=\"gram\">[transitive]</span> to own and look after animals:</div><ul class=\"examples\"><li><em>We keep chickens and a couple of pigs.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>[stop other people from using something]</strong> <span class=\"gram\">[transitive]</span> to stop other people from using something, so that it is available for someone <em>SYN save</em>:</div><ul class=\"examples\"><li><em>Will you keep a seat for me?</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>keep somebody waiting</strong> to make someone wait before you meet them or see them:</div><ul class=\"examples\"><li><em>Sorry to keep you waiting – I got stuck in a meeting.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>keep guard/watch</strong> to guard a place or watch around you all the time</div><div class=\"sense\"><span class=\"snum\">18</span> <strong>[shop]</strong> <span class=\"gram\">[transitive]</span> <em>British English</em> <em>old-fashioned</em> to own a small business and work in it</div><div class=\"sense\"><span class=\"snum\">19</span> <strong>[provide somebody with things]</strong> <span class=\"gram\">[transitive]</span> to provide someone with money, food etc:</div><ul class=\"examples\"><li><em>He did not earn enough to keep a wife and children.</em></li><li><strong><em>keep somebody in something</strong>: There’s enough money there to keep you in champagne for a year!</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>[protect]</strong> <span class=\"gram\">[transitive]</span> <em>formal</em> to guard or protect someone:</div><ul class=\"examples\"><li><em>The Lord bless you and keep you.</em></li><li><em>His only thought was to keep the child from harm.</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>keep goal/wicket</strong> to be the player in a team whose job is to protect the goal or wicket → goalkeeper, wicket keeper</div></div>","3894":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ketch‧up</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈketʃəp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a thick cold red sauce made from tomatoes that you put on food:</div><ul class=\"examples\"><li><em>a bottle of tomato ketchup</em></li></ul></div>","3895":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ket‧tle</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈketl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a container with a lid, a handle, and a spout, used for boiling and pouring water SYN teakettle<em>American English</em>:</div><ul class=\"examples\"><li><em>She filled the kettle and switched it on.</em></li><li><em>The kettle’s boiling (=the water in it is boiling).</em></li><li><em>Put the kettle on (=start boiling water in a kettle), will you?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>American English</em> a large pot, used for making soup</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>another/a different kettle of fish</strong> <em>informal</em> used to say that a situation is very different from one that you have just mentioned:</div><ul class=\"examples\"><li><em>She enjoys public speaking, but being on TV is a different kettle of fish.</em></li></ul></div>","3896":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /kiː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[lock]</strong> a small specially shaped piece of metal that you put into a lock and turn in order to lock or unlock a door, start a car etc ► Don’t say ‘the key of’ something. Say the key to something. → master key</div><ul class=\"examples\"><li><strong><em>house/car keys</strong>: I lost my house keys.</em></li><li><em>A bunch of keys hung from his belt.</em></li><li><strong><em>key to</strong>: I can lend you a spare key to the store until you get one cut (=made).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[important part]</strong> <strong>the key</strong> the part of a plan, action etc that will make it possible for it to succeed</div><ul class=\"examples\"><li><strong><em>key to</strong>: Working well as a team is the key to success. / a discovery that may hold the key to our understanding of the universe</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[computer]</strong> the buttons that you press on a computer keyboard to operate the computer:</div><ul class=\"examples\"><li><em>Press the ‘Escape’ key to exit.</em></li><li><strong><em>hot key/shortcut key</strong> (=a special key on a computer, that does specific things)</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[music]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[usually plural]</span> the wooden or metal parts that you press on a piano and some wind instruments in order to play them:</div><ul class=\"examples\"><li><em>piano keys</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a scale of notes that begins with one particular note, or the quality of sound this scale has:</div><ul class=\"examples\"><li><em>a tune in the key of A minor</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[map/drawing]</strong> a list of the signs, colours etc used on a map or technical drawing etc that explains what they mean</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[test]</strong> the printed answers to a test or set of questions in a book</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[island]</strong> <span class=\"gram\">[usually plural]</span> a small flat island, especially one that is part of a group near the coast:</div><ul class=\"examples\"><li><em>the Florida Keys</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W2</span><span class=\"meta-item\"><span class=\"gram\">[no comparative]</span></span></div><div class=\"entry-body\"><div class=\"sense\">very important or necessary: ► see thesaurus at important, main</div><ul class=\"examples\"><li><em>China’s support is key to the success of the coalition.</em></li><li><strong><em>key factor/points/questions etc</em></strong></li><li><em>The president makes all the key decisions on foreign policy.</em></li><li><strong><em>key role/player/figure etc</strong> (=one with a lot of influence on a result): The show has been hit by the departure of key personnel.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>American English</em> <em>informal</em> if you key a win for your team, you help it win a game because you play very well:</div><ul class=\"examples\"><li><em>Abdul keyed the game with three touchdowns.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>British English</em> to prepare a surface so that a covering such as paint will stick to it</div></div></div>","3897":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> key‧board</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈkiːbɔːd $ -bɔːrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a board with buttons marked with letters or numbers that are pressed to put information into a computer or other machine:</div><ul class=\"examples\"><li><em>a computer keyboard</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the row of keys on some musical instruments that you press in order to play them</div><div class=\"sense\"><span class=\"snum\">3</span> (also keyboards) <span class=\"gram\">[plural]</span> an electronic musical instrument similar to a piano that can make sounds like many different instruments → synthesizer:</div><ul class=\"examples\"><li><em>Chris Kelly (guitar) and Benny Hayes (keyboards and vocals)</em></li></ul></div>","3898":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /kɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to hit something with your foot</div><ul class=\"examples\"><li><strong><em>kick something down/over/around etc</strong>: Billy was kicking a ball around the yard. / The police kicked the door down.</em></li><li><strong><em>kick somebody in the stomach/face/shin etc</strong>: There was a scuffle and he kicked me in the stomach.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to move your legs as if you are kicking something:</div><ul class=\"examples\"><li><em>He kicked off his shoes and lay back on the bed.</em></li><li><em>a row of dancers kicking their legs in the air</em></li><li><em>A horse trotted past, kicking up dust from the road.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>kick yourself</strong> <em>spoken</em> used to say that you are annoyed with yourself because you have done something silly, made a mistake etc:</div><ul class=\"examples\"><li><em>You’ll kick yourself when I tell you the answer.</em></li><li><em>United will be kicking themselves for missing several chances.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>kick the habit</strong> to stop doing something that is a harmful habit, such as smoking, taking drugs etc:</div><ul class=\"examples\"><li><em>The scheme helps smokers to kick the habit.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>kick somebody when they are down</strong> to criticize or attack someone who is already in a weak or difficult position:</div><ul class=\"examples\"><li><em>The media can’t resist kicking a man when he’s down.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>kick somebody in the teeth</strong> (also kick somebody in the stomach/pants<em>American English</em>) <em>informal</em> to disappoint someone or treat them badly at a time when they need help:</div><ul class=\"examples\"><li><em>We all have times when life kicks us in the teeth.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>kick somebody’s ass/butt</strong> <em>American English</em> <em>informal</em> <em>not polite</em> to punish or defeat someone:</div><ul class=\"examples\"><li><em>· We’re gonna kick San Francisco’s ass good tonight.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>kick ass</strong> <em>American English</em> <em>informal</em> <em>not polite</em> used to say that someone or something is very good or impressive:</div><ul class=\"examples\"><li><em>· Tucson pop band Shoebomb kick some serious ass.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>kick your heels</strong> <em>British English</em> to waste time waiting for something:</div><ul class=\"examples\"><li><em>We were left kicking our heels for half the day.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>kick up your heels</strong> to enjoy yourself a lot at a party, event etc:</div><ul class=\"examples\"><li><em>The charity ball is a chance to kick up your heels and help a good cause.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>kick something into touch</strong> <em>British English</em> <em>informal</em> to stop a plan or project before it is completed:</div><ul class=\"examples\"><li><em>A hitch resulted in the deal being kicked firmly into touch.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>kick up a fuss/stink/row</strong> <em>informal</em> to complain loudly about something:</div><ul class=\"examples\"><li><em>Won’t he kick up a fuss when he discovers they’re missing?</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>kicking and screaming</strong> protesting violently or being very unwilling to do something:</div><ul class=\"examples\"><li><em>The company was dragged kicking and screaming into the 21st century.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>kick the shit out of somebody</strong> <em>informal</em> <em>not polite</em> to hurt someone very badly by kicking them many times</div><div class=\"sense\"><span class=\"snum\">15</span> <strong>kick against the pricks</strong> <em>British English</em> <em>informal</em> to hurt or damage yourself by trying to change something that cannot be changed</div><div class=\"sense\"><span class=\"snum\">16</span> <strong>kick somebody upstairs</strong> to move someone to a new job that seems to be more important than their last one, but that actually gives them less influence</div><div class=\"sense\"><span class=\"snum\">17</span> <strong>be kicking (it)</strong> <em>American English</em> <em>spoken</em> to be relaxing and having a good time:</div><ul class=\"examples\"><li><em>I was just kicking with my buddies.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>be kicking it</strong> <em>American English</em> <em>spoken</em> to be having a romantic or sexual relationship with someone</div><ul class=\"examples\"><li><strong><em>kick with</strong>: My sources say that she was kicking it with Thomas while she was on tour.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>kick over the traces</strong> <em>British English</em> <em>old-fashioned</em> to start behaving badly by refusing to accept any control or rules</div><div class=\"sense\"><span class=\"snum\">20</span> <strong>kick the bucket</strong> <em>old-fashioned</em> to die – used humorously</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a movement of your foot or leg, usually to hit something with your foot:</div><ul class=\"examples\"><li><em>Brazil scored with the last kick of the match.</em></li><li><em>Rory aimed a kick at her leg and missed.</em></li><li><em>kung fu kicks</em></li><li><em>If the door won’t open, just give it a good kick.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the act of kicking the ball in a sports game such as football, or the ball that is kicked and the direction it goes in:</div><ul class=\"examples\"><li><em>Benjamin struck a post with an overhead kick.</em></li><li><strong><em>free/penalty kick</strong> (=an opportunity, allowed by the rules, for a player in one team to kick the ball without being stopped by the other team): Pearce came forward to take the free kick.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> something that you enjoy because it is exciting <em>SYN thrill</em></div><ul class=\"examples\"><li><strong><em>get a kick out of/from (doing) something</strong>: Gerald gets a kick out of dressing as a woman.</em></li><li><strong><em>give somebody a kick</strong>: It gives her a kick to get you into trouble.</em></li><li><strong><em>do something (just) for kicks</strong>: She used to steal from shops for kicks.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>a kick up the arse/backside/pants etc</strong> <em>informal</em> criticism or strong encouragement to make someone do something they should have done:</div><ul class=\"examples\"><li><em>What Phil needs is a good kick up the arse.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>a kick in the teeth</strong> <em>informal</em> something that is very disappointing or upsetting that happens when you need support:</div><ul class=\"examples\"><li><em>This broken promise is a real kick in the teeth for our fans.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>a kick</strong> <em>informal</em> used to talk about the strong effect of a drink or drug or the strong taste that some food has:</div><ul class=\"examples\"><li><em>The wine had a real kick.</em></li></ul></div></div>","3899":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /kɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> <em>informal</em> a child: ► see thesaurus at child RegisterKid is informal. For formal or written styles use child:· Research suggests that children from abusive families are likely to repeat violent behaviour.</div><ul class=\"examples\"><li><em>She’d always loved animals since she was a little kid.</em></li><li><em>He’s married with three kids.</em></li><li><em>A neighbor volunteered to keep an eye on the kids (=their children or the children they are responsible for).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> <em>informal</em> a young person:</div><ul class=\"examples\"><li><em>college kids</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable usually singular]</span> used by adults to address a person who is younger than them:</div><ul class=\"examples\"><li><em>Hey kid, come here.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>kid’s stuff</strong> (also kid stuff<em>American English</em>) something that is too easy or boring:</div><ul class=\"examples\"><li><em>Pokémon? Oh boy, that is kid stuff!</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[countable]</span> a young goat</div><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[uncountable]</span> very soft leather made from the skin of a young goat:</div><ul class=\"examples\"><li><em>a pair of white kid boots</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>kid gloves</strong> a way of treating someone kindly and carefully because they easily become upset</div><ul class=\"examples\"><li><strong><em>treat/handle somebody with kid gloves</strong>: I want you to treat Hayley with kid gloves today. She’s still upset about her father.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(past tense and past participle kidded, present participle kidding)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to say something that is not true, especially as a joke <em>SYN joke</em></div><ul class=\"examples\"><li><strong><em>just/only kidding</strong>: Don’t get mad – I was only kidding.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to make jokes or say funny things about someone in a friendly way <em>SYN tease</em></div><ul class=\"examples\"><li><strong><em>kid somebody about something</strong>: We were kidding Mom about being a grandmother.</em></li><li><strong><em>kid somebody (that)</strong>: My friends kidded me that my gear would fill the car.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>no kidding?/are you kidding?/you’re kidding</strong> <em>spoken</em> used when you are so surprised by what someone has told you that you do not completely believe them:</div><ul class=\"examples\"><li><em>Carlotta’s 39? No kidding?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>no kidding</strong> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to say that you understand and agree with what someone has just said:</div><ul class=\"examples\"><li><em>‘That girl has some major problems.’ ‘Yeah, no kidding.’</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to emphasize a threat or that you are telling the truth:</div><ul class=\"examples\"><li><em>If you break that thing, you’ll be grounded for a week – no kidding.</em></li><li><em>And then he saw us and – no kidding – he asked us if we wanted a ride.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[transitive]</span> to let yourself believe something that is untrue or unlikely</div><ul class=\"examples\"><li><strong><em>kid yourself (that)</strong>: Don’t kid yourself he’ll ever change.</em></li><li><em>We thought we could change the world. Just who were we trying to kid?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>I kid you not</strong> <em>spoken</em> used to emphasize that you are telling the truth</div></div></div>","3900":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> kid‧nap</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈkɪdnæp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle kidnapped, present participle kidnapping also kidnaped, kidnaping American English)</span></div><div class=\"entry-body\"><div class=\"sense\">to take someone somewhere illegally by force, often in order to get money for returning them → ransom:</div><ul class=\"examples\"><li><em>Police appealed for witnesses after a woman was kidnapped at gunpoint.</em></li></ul></div>","3901":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> kid‧ney</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈkɪdni/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> one of the two organs in your lower back that separate waste products from your blood and make urine:</div><ul class=\"examples\"><li><em>a kidney transplant</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> one or more of these organs from an animal, used as food:</div><ul class=\"examples\"><li><em>steak and kidney pie</em></li></ul></div>","3902":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /kɪl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[make somebody/something die]</strong> <span class=\"gram\">[intransitive, transitive]</span> to make a person or animal die:</div><ul class=\"examples\"><li><em>Why did she kill her husband?</em></li><li><em>Murray held a gun to his head and threatened to kill him.</em></li><li><em>Four people were killed when a train plunged into a flooded river.</em></li><li><strong><em>be killed instantly/outright</strong> (=immediately): The driver was killed instantly.</em></li><li><em>Bleach kills household germs.</em></li><li><em>Smoking kills.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>kill yourself</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to cause your own death:</div><ul class=\"examples\"><li><em>You’re going to kill yourself on that bike.</em></li><li><em>After her husband died, Mary tried to kill herself.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to work very hard to achieve something, in a way that makes you ill or tired:</div><ul class=\"examples\"><li><em>It’s not worth killing yourself over it.</em></li><li><strong><em>kill yourself to do something</strong>: He about killed himself to make the business go.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[make something stop/fail]</strong> <span class=\"gram\">[transitive]</span> to make something stop operating or fail:</div><ul class=\"examples\"><li><em>Joe pulled in and killed the engine.</em></li><li><em>The out-of-town shopping centre will kill local trade.</em></li><li><strong><em>kill your speed</strong> (=drive slowly)</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[be angry with somebody]</strong> <span class=\"gram\">[transitive]</span> <em>informal</em> to be very angry with someone:</div><ul class=\"examples\"><li><em>Mom will kill me if I’m late.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[annoyed/sad]</strong> <span class=\"gram\">[transitive]</span> to make someone feel annoyed, sad, concerned etc</div><ul class=\"examples\"><li><strong><em>it kills somebody to do something</strong>: It kills me to see him working so hard.</em></li><li><em>What happened next? The suspense is killing me.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>would/could kill for something</strong> (also would kill to do something) to want something so much that you will do almost anything to get it or do it:</div><ul class=\"examples\"><li><em>I could kill for a smoke right now.</em></li><li><em>In those days, actors would kill to break into film.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>my head/back etc is killing me</strong> <em>spoken</em> used to say that a part of your body is hurting a lot:</div><ul class=\"examples\"><li><em>I’ve walked miles and my feet are killing me.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>kill time/an hour etc</strong> to spend time doing something which is not important, while you are waiting to do something important or waiting for something else to happen:</div><ul class=\"examples\"><li><em>With time to kill, he took a cab to the centre.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>kill a beer/bottle of wine etc</strong> <em>spoken</em> to drink or finish drinking a beer etc quickly:</div><ul class=\"examples\"><li><em>Let’s kill these beers and go.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[make somebody laugh]</strong> <span class=\"gram\">[transitive]</span> to make someone laugh a lot</div><ul class=\"examples\"><li><strong><em>kill yourself laughing</strong>: They weren’t bothered – in fact, they were killing themselves laughing.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>it won’t/wouldn’t kill somebody (to do something)</strong> <em>spoken</em> used to say that someone could easily do something, and ought to do it:</div><ul class=\"examples\"><li><em>It wouldn’t kill you to help out once in a while.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>(even) if it kills me</strong> <em>spoken</em> used to emphasize that you are determined to do something, even though it is very difficult:</div><ul class=\"examples\"><li><em>I’m completing this course, even if it kills me.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>kill two birds with one stone</strong> to achieve two things with one action</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>kill the goose that lays the golden egg</strong> to destroy the thing that brings you profit or success</div><div class=\"sense\"><span class=\"snum\">15</span> <strong>kill the fatted calf</strong> to welcome someone home with a big meal etc after they have been away for a long time</div><div class=\"sense\"><span class=\"snum\">16</span> <strong>kill somebody with kindness</strong> to be too kind to someone, in a way that actually harms them</div><div class=\"sense\"><span class=\"snum\">17</span> <strong>kill or cure</strong> used to say that something you are going to do will be either successful or fail completely</div></div>","3903":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> kill‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈkɪlə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a person, animal, or thing that kills: → serial killer at serial2(1)</div><ul class=\"examples\"><li><em>Heart disease is America’s number one killer.</em></li><li><em>the hunt for her killers</em></li><li><em>weed killer</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>informal</em> something or someone that is very difficult, tiring, or boring:</div><ul class=\"examples\"><li><em>The new project is a killer.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>informal</em> something that is very exciting or impressive:</div><ul class=\"examples\"><li><em>I’m not saying the film is a killer, but it’s cool.</em></li></ul></div>","3904":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> kill‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈkɪlɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the act of killing someone deliberately <em>SYN murder</em>:</div><ul class=\"examples\"><li><em>a series of gangland killings</em></li><li><em>They murdered fifteen boys in a killing spree (=an occasion when someone murders many people in a short period of time) across southern California.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>make a killing</strong> <em>informal</em> to make a lot of money in a short time:</div><ul class=\"examples\"><li><em>He made a killing on the stock exchange.</em></li></ul></div>","3905":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ki‧lo</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈkiːləʊ $ -loʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural kilos)</span></div><div class=\"entry-body\"><div class=\"sense\">a kilogram</div></div>","3906":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> kil‧o‧gram</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈkɪləɡræm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a unit for measuring weight, equal to 1,000 grams</div></div>","3907":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> kil‧o‧me‧tre</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈkɪləˌmiːtə, kɪˈlɒmɪtə $ kɪˈlɑːmɪtər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a unit for measuring distance, equal to 1,000 metres</div></div>","3908":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /kaɪnd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> one of the different types of a person or thing that belong to the same group <em>SYN sort, type</em></div><ul class=\"examples\"><li><strong><em>kind of</strong>: They sell all kinds of things.</em></li><li><em>The flowers attract several different kinds of insects.</em></li><li><em>Greg was working on some kind of deal in Italy.</em></li><li><em>Get me a sandwich – any kind will do.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the kind</strong> used to describe a person with a particular character, feelings, opinions etc:</div><ul class=\"examples\"><li><em>Ted just isn’t the marrying kind.</em></li><li><em>Rob isn’t the kind to worry.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>somebody’s kind of person/thing/place etc</strong> the type of person, thing, place etc that someone usually likes:</div><ul class=\"examples\"><li><em>It’s not my kind of place – it’s too quiet.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>kind of</strong> (also kinda<em>American English</em>) <em>spoken</em> slightly but not exactly, or in some ways <em>SYN sort of</em>:</div><ul class=\"examples\"><li><em>I’m kind of glad I didn’t win.</em></li><li><em>He’s kinda dumb, isn’t he?</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>a kind of (a) something</strong> <em>spoken</em> used to say that your description of something is not exact:</div><ul class=\"examples\"><li><em>a kind of reddish-brown color</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>two/three etc of a kind</strong> two, three etc people or things that are very similar:</div><ul class=\"examples\"><li><em>You and Joe are two of a kind.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>one of a kind</strong> the only one of a particular type of thing:</div><ul class=\"examples\"><li><em>Each plate is handpainted and one of a kind.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>something of the/that kind</strong> <em>spoken</em> something similar to what was expected or talked about:</div><ul class=\"examples\"><li><em>Rosa was shocked by the news, although she had suspected something of the kind might happen.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>nothing/anything of the kind</strong> <em>spoken</em> used to emphasize that what has been said is not true:</div><ul class=\"examples\"><li><em>I never said anything of the kind!</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>of a kind</strong> used to say that something is not as good as it should be:</div><ul class=\"examples\"><li><em>Elections of a kind are held, but there is only one party to vote for.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>in kind</strong> reacting to something someone has done by doing the same thing:</div><ul class=\"examples\"><li><em>After recent bombings, counter-terrorist forces could retaliate in kind.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\">(comparative kinder, superlative kindest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> saying or doing things that show that you care about other people and want to help them or make them happy <em>OPP unkind</em> → kindly, kindness GRAMMARYou are kind to someone: · He was kind to her. ✗Don’t say: He was kind with her.Grammar guide ‒ ADJECTIVES</div><ul class=\"examples\"><li><strong><em>kind to</strong>: They’ve been very kind to me.</em></li><li><em>It wasn’t a very kind thing to say.</em></li><li><em>She’s a very kind and generous person.</em></li><li><strong><em>it’s kind of somebody (to do something)</strong>: It’s kind of you to say that. / It’s really kind of them to let us use their pool.</em></li><li><em>We thanked the priest for his kind words.</em></li><li><em>Thank you for your help. You’ve been most kind (=said when thanking someone very politely).</em></li><li><strong><em>thank you for your kind invitation/offer</strong> (=said when thanking someone very politely for their invitation or offer)</em></li><li><em>Ms Jarvis is unable to accept your kind invitation.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> not causing harm or suffering</div><ul class=\"examples\"><li><strong><em>kind to</strong>: Life has been very kind to me. / I need a soap that’s kinder to my skin.</em></li><li><em>Let’s hope the weather’s kind tomorrow.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>would you be kind enough to do something/be so kind as to do something</strong> <em>formal</em> used to make a polite request: RegisterIn everyday English, people usually say please could you...? or would you mind...? because the expressions with kind can sound too formal and unfriendly:· Would you mind closing the door?</div><ul class=\"examples\"><li><em>Would you be kind enough to close the door, please?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>kind regards</strong> <em>written</em> used to end a formal but fairly friendly letter</div></div></div>","3909":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> kind‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈkaɪndli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in a kind way <em>SYN generously</em></div><ul class=\"examples\"><li><strong><em>kindly offer/agree/give etc</strong>: Mr Nunn has kindly agreed to let us use his barn for the dance.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>not take kindly to something</strong> to be unwilling to accept a situation because it annoys you:</div><ul class=\"examples\"><li><em>She does not take kindly to criticism.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>look kindly on somebody/something</strong> to approve of someone or something:</div><ul class=\"examples\"><li><em>Jimmy would probably not look too kindly on our request.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>spoken</em> <em>formal</em> a word meaning ‘please’, which is often used when you are annoyed:</div><ul class=\"examples\"><li><em>Will you kindly put that book back?</em></li></ul></div>","3910":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> kind‧ness</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈkaɪndnəs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> kind behaviour towards someone: RegisterIn everyday English, when you are thanking people for helping you, the normal phrase to use is Thanks for (all) your help. The phrase Thank you for your kindness sounds very polite and slightly old-fashioned.</div><ul class=\"examples\"><li><em>I can’t thank you enough for your kindness.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a kind action</div><ul class=\"examples\"><li><strong><em>do somebody a kindness</strong>: It would be doing him a kindness to tell him the truth.</em></li></ul></div>","3911":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /kɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[ruler]</strong> (also King) a man who rules a country because he is from a royal family → queen</div><ul class=\"examples\"><li><strong><em>king of</strong>: Henry VIII, King of England</em></li><li><em>On 2 December Henry VI was crowned king (=made the king at an official ceremony).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[the best]</strong> <strong>the king of something</strong> someone or something that people think is the most important or best of a particular type of person or thing:</div><ul class=\"examples\"><li><em>the King of Rock ‘n’ Roll</em></li><li><em>the king of Swiss cheeses</em></li><li><em>The lion is the king of the jungle.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[successful]</strong> if you live like a king, feel like a king etc, you are very successful, happy, rich etc:</div><ul class=\"examples\"><li><em>With her at my side, I felt like a king.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[chess]</strong> the most important piece in chess</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[cards]</strong> a playing card with a picture of a king on it</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[important]</strong> <strong>be king</strong> if something is king at a particular time, it has a big influence on people:</div><ul class=\"examples\"><li><em>back in the days when jazz was king</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>a king’s ransom</strong> a very large amount of money</div></div>","3912":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> king‧dom</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈkɪŋdəm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a country ruled by a king or queen:</div><ul class=\"examples\"><li><em>the United Kingdom</em></li><li><strong><em>kingdom of</strong>: the kingdom of Thailand</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the animal/plant/mineral kingdom</strong> one of the three parts into which the natural world is divided</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>the kingdom of heaven/God</strong> (also God’s kingdom) heaven</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>kingdom come</strong> <em>informal</em> a phrase used to describe the end of the world, death, or the end of time:</div><ul class=\"examples\"><li><em>He left the gas on and nearly blew us all to kingdom come.</em></li></ul></div>","3913":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /kɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to touch someone with your lips as a greeting, to show them love, or as part of a sexual relationship: GRAMMAR: Reciprocal verbsKiss is a reciprocal verb. This type of verb is used when saying that two or more people do something that involves both or all of them. It does not need to have an object: · We kissed. In this sentence, kiss is intransitive and does not have an object.You can also say: · We kissed each other.· I kissed her. In these sentences, kiss is transitive.Grammar guide ‒ VERBS</div><ul class=\"examples\"><li><em>Maggie leaned forward and kissed her cheek.</em></li><li><em>Georgina took him in her arms and kissed him on the lips.</em></li><li><em>Jim and Mary kissed (=they kissed each other).</em></li><li><strong><em>kiss somebody gently/lightly</strong>: He kissed her gently and stroked her hair.</em></li><li><strong><em>kiss somebody goodbye/good night etc</strong>: Kiss Daddy good night.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to touch something with your lips as a sign of respect:</div><ul class=\"examples\"><li><em>She raised the crucifix to her lips and kissed it.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>kiss goodbye to something/kiss something goodbye</strong> <em>informal</em> to accept that you will lose something or lose an opportunity to do something:</div><ul class=\"examples\"><li><em>She knew if she concentrated on her marriage she could kiss her career goodbye.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>kiss something better</strong> <em>spoken</em> used, especially to a child, to say that you will take away the pain of something by kissing them:</div><ul class=\"examples\"><li><em>Here, let Mommy kiss it better.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>kiss my ass</strong> <em>American English</em> <em>informal</em> <em>not polite</em> an insulting expression used to show that you do not respect someone</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>kiss (somebody’s) ass</strong> <em>American English</em> <em>informal</em> <em>not polite</em> to be too nice to someone who can give you something you want – used to show disapproval</div><div class=\"sense\"><span class=\"snum\">7</span> <span class=\"gram\">[transitive]</span> <em>literary</em> if the wind, sun etc kisses something, it gently moves or touches it</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an act of kissing:</div><ul class=\"examples\"><li><em>Do you remember your first kiss?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>give somebody the kiss of life</strong> <em>especially British English</em> to make someone start breathing again by blowing air into their lungs when they have almost drowned etc</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>the kiss of death</strong> <em>informal</em> something that spoils or ruins a plan, activity etc</div></div></div>","3914":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /kɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a set of tools, equipment etc that you use for a particular purpose or activity:</div><ul class=\"examples\"><li><em>Sally keeps her make-up kit in her bag.</em></li><li><em>a bike repair kit</em></li><li><em>a shaving kit</em></li><li><em>a drum kit</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> something that you buy in parts and put together yourself:</div><ul class=\"examples\"><li><em>model kits for making boats</em></li><li><em>kit cars</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> electronic equipment, especially computers and computer software:</div><ul class=\"examples\"><li><em>The new kit includes wireless keyboard and gaming headset.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable, uncountable]</span> <em>British English</em> a set of clothes and equipment that you use for a particular purpose such as playing a sport:</div><ul class=\"examples\"><li><em>sports kit</em></li><li><em>football kits</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[uncountable]</span> a set of clothes and equipment used by soldiers, sailors etc:</div><ul class=\"examples\"><li><em>The soldiers are trained to jump from the planes with full kit on.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>get your kit off</strong> <em>British English</em> <em>informal</em> to take your clothes off</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>the whole kit and caboodle</strong> <em>old-fashioned</em> everything</div></div>","3915":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> kitch‧en</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈkɪtʃɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the room where you prepare and cook food:</div><ul class=\"examples\"><li><em>Sam went into the kitchen to make a pot of tea.</em></li><li><em>She is in the kitchen making a meal.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>everything but the kitchen sink</strong> <em>humorous</em> used when someone has brought too many things with them</div></div>","3916":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /kaɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a light frame covered in coloured paper or plastic that you let fly in the air on the end of one or two long strings</div><div class=\"sense\"><span class=\"snum\">2</span> a type of hawk (=bird that eats small animals)</div><div class=\"sense\"><span class=\"snum\">3</span> <em>American English</em> <em>informal</em> an illegal cheque</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>fly a kite</strong> to make a suggestion to see what people will think of it</div></div>","3917":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> kit‧ten</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈkɪtn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a young cat</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>have kittens</strong> <em>British English</em> <em>spoken</em> <em>informal</em> to be very anxious or upset about something</div></div>","3918":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /niː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the joint that bends in the middle of your leg:</div><ul class=\"examples\"><li><em>Lucy had a bandage round her knee.</em></li><li><strong><em>on your knees</strong>: She was on her knees (=kneeling), weeding the garden.</em></li><li><strong><em>sink/fall/drop to your knees</strong> (=move so that you are kneeling): Tim fell to his knees and started to pray.</em></li><li><em>a knee injury</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the part of your clothes that covers your knee:</div><ul class=\"examples\"><li><em>His jeans had holes in both knees.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>on somebody’s knee</strong> on the top part of your legs when you are sitting down:</div><ul class=\"examples\"><li><em>Daddy, can I sit on your knee?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>knees knocking (together)</strong> if your knees are knocking, you are feeling very afraid or very cold</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>on your knees</strong> in a way that shows you have no power but want or need something very much:</div><ul class=\"examples\"><li><em>He went on his knees begging for his job back.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>bring somebody/something to their knees</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to defeat a country or group of people in a war:</div><ul class=\"examples\"><li><em>The bombing was supposed to bring the country to its knees.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to have such a bad effect on an organization, activity etc that it cannot continue <em>SYN cripple</em>:</div><ul class=\"examples\"><li><em>The recession has brought many companies to their knees.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>put/take somebody over your knee</strong> <em>old-fashioned</em> to punish a child by hitting them</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>on bended knee(s)</strong> <em>old-fashioned</em> in a way that shows great respect for someone</div></div>","3919":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /niːl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span><span class=\"meta-item\">(past tense and past participle knelt /nelt/ or kneeled American English)</span></div><div class=\"entry-body\"><div class=\"sense\">to be in or move into a position where your body is resting on your knees:</div><ul class=\"examples\"><li><em>Tom knelt down and patted the dog.</em></li><li><strong><em>kneel on</strong>: She knelt on the floor and put more wood on the fire.</em></li></ul></div>","3920":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /naɪf/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural knives /naɪvz/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a metal blade fixed into a handle, used for cutting or as a weapon → scalpel: → carving knife, flick knife, palette knife, paper knife, penknife</div><ul class=\"examples\"><li><em>a knife and fork</em></li><li><em>Some young people are carrying knives to defend themselves.</em></li><li><em>a kitchen knife</em></li><li><em>Use a sharp knife to cut the melon into sections.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the knives are out (for somebody)</strong> <em>informal</em> used to say that people are being extremely unfriendly in criticizing someone:</div><ul class=\"examples\"><li><em>The knives are out for the vice president.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>twist/turn the knife (in the wound)</strong> to say something that makes someone more upset about a subject they are already unhappy about</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>stick/put etc the knife in/into someone</strong> <em>British English</em> <em>informal</em> to dislike someone and be very unfriendly towards them</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>under the knife</strong> <em>informal</em> having a medical operation</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>you could cut the atmosphere/air/tension with a knife</strong> used to say that you felt the people in a room were angry with each other</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>like a (hot) knife through butter</strong> <em>informal</em> used to say that something happens or is done very easily, without any problems</div></div>","3921":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /naɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a man with a high rank in the past who was trained to fight while riding a horse: → white knight</div><ul class=\"examples\"><li><em>knights in armour</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a man who has received a knighthood and has the title sir before his name</div><div class=\"sense\"><span class=\"snum\">3</span> the chess piece with a horse’s head on it</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>a knight in shining armour</strong> a brave man who saves someone, especially a woman, from a dangerous situation</div></div>","3922":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /nɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span><span class=\"meta-item\">(present participle knitting)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> (past tense and past participle knitted) to make clothing out of wool, using two knitting needles → crochet:</div><ul class=\"examples\"><li><em>My grandmother taught me how to knit.</em></li><li><em>She’s knitting a sweater.</em></li><li><strong><em>knit somebody something</strong>: Emily knitted him some socks.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> (past tense and past participle knitted) to use a plain (=basic) knitting stitch:</div><ul class=\"examples\"><li><em>Knit one, purl one.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> (past tense and past participle knit) to join people, things, or ideas more closely together, or to be joined closely together</div><ul class=\"examples\"><li><strong><em>knit together</strong>: In a good report, individual sentences knit together in a clear way that readers can follow.</em></li><li><strong><em>closely/tightly etc knit</strong> (=with all the members having close relationships): a closely knit community / Harold is part of a tightly knit team.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> (past tense and past participle knit) a bone that knits after being broken grows into one piece again</div><ul class=\"examples\"><li><strong><em>knit together</strong>: The pin holds the bones in place while they knit together.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>knit your brows</strong> to show you are worried, thinking hard etc by moving your eyebrows together</div></div>","3923":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> knit‧ting</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈnɪtɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> something that is being knitted</div><div class=\"sense\"><span class=\"snum\">2</span> the activity or action of knitting clothes</div></div>","3924":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /nɒk $ nɑːk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[door]</strong> <span class=\"gram\">[intransitive]</span> to hit a door or window with your closed hand to attract the attention of the people inside: ► see thesaurus at hit</div><ul class=\"examples\"><li><em>I knocked and knocked but nobody answered.</em></li><li><strong><em>knock at/on</strong>: We knocked at the door but there was no one there.</em></li><li><em>Wilson went up and knocked on the door.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[hit and move something]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to hit something with a short quick action so that it moves or falls</div><ul class=\"examples\"><li><strong><em>knock something out of/from something</strong>: As I got up, I knocked a pencil out of its holder. / He knocked the knife from my hand.</em></li><li><strong><em>knock something over</strong>: At that moment, Sally knocked over her glass of wine.</em></li><li><strong><em>knock something aside</strong>: She tried to knock the gun aside but she was not fast enough.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[hit somebody hard]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to hit someone very hard:</div><ul class=\"examples\"><li><em>He knocked her to the ground and kicked her.</em></li><li><strong><em>knock somebody unconscious/cold/senseless</strong> (=hit someone so hard that they fall unconscious): Simon could knock a man unconscious with one punch to the jaw.</em></li><li><em>Garry answered the door only to be knocked flying as two policemen came rushing in.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[hit part of your body]</strong> <span class=\"gram\">[transitive]</span> to hit something with part of your body</div><ul class=\"examples\"><li><strong><em>knock something against something</strong>: Morse knocked his shin against a suitcase that had been left just inside the door.</em></li><li><strong><em>knock something on something</strong>: She knocked her head on a stone.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>knock on doors</strong> to go to every house or apartment in an area asking the people who live there for information or support:</div><ul class=\"examples\"><li><em>Gathering that information means knocking on doors and asking people questions.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be knocking on the door</strong> to be wanting to join a group or team – used in news reports:</div><ul class=\"examples\"><li><em>Five countries have permanent seats on the UN Security Council, but Germany and Japan, among others, are knocking on the door.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[remove wall]</strong> <span class=\"gram\">[transitive]</span> to remove a wall or part of a building in order to make a bigger room or space</div><ul class=\"examples\"><li><strong><em>knock something into something</strong>: We could make a bigger living space by knocking two rooms into one.</em></li><li><strong><em>knock something through</strong>: The wall between the kitchen and the dining room has been partially knocked through.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>knock a hole in/through something</strong> to make a hole in something, especially a wall:</div><ul class=\"examples\"><li><em>We could knock a hole through the wall into the cupboard.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[criticize]</strong> <span class=\"gram\">[transitive]</span> to criticize someone or their work, especially in an unfair or annoying way: ► see thesaurus at criticize</div><ul class=\"examples\"><li><em>The British press always knock British winners at any sport.</em></li><li><em>‘Designer fashion is silly.’ ‘Don’t knock it; it’s an important industry.’</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[ball]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to kick or hit a ball somewhere:</div><ul class=\"examples\"><li><em>The aim is to knock the ball into the opposing goal.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>knock somebody for six</strong> <em>British English</em> <em>informal</em> to shock or upset someone very much or make them physically weak:</div><ul class=\"examples\"><li><em>This flu has really knocked me for six.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>knock the stuffing out of somebody</strong> <em>informal</em> to make someone lose their confidence:</div><ul class=\"examples\"><li><em>Suzanne was very upset when her mother left home. It knocked the stuffing out of her.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>knock somebody sideways</strong> <em>British English</em> to upset someone so much that it is difficult for them to deal with something:</div><ul class=\"examples\"><li><em>His daughter’s death knocked Tom sideways.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>knock some sense into somebody/into somebody’s head</strong> <em>informal</em> to make someone learn to behave in a more sensible way:</div><ul class=\"examples\"><li><em>The struggle to build up her own business had knocked some sense into her.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>knock (somebody’s) heads together</strong> <em>informal</em> to tell people who are arguing that they must stop and behave more sensibly:</div><ul class=\"examples\"><li><em>None of them can agree and it needs someone to knock heads together.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>knock something on the head</strong> <em>British English</em> <em>informal</em> to stop something happening:</div><ul class=\"examples\"><li><em>We wanted to go for a picnic, but the rain’s knocked that on the head.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>knock somebody’s socks off</strong> (also knock somebody dead) <em>spoken</em> to surprise and please someone by being very impressive:</div><ul class=\"examples\"><li><em>With that dress, you’ll knock him dead.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>knock somebody off their pedestal/perch</strong> to stop admiring someone that you previously thought was perfect:</div><ul class=\"examples\"><li><em>The press were determined to knock the princess off the pedestal that they had put her on.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>knock spots off somebody/something</strong> <em>British English</em> <em>spoken</em> to be much better than someone or something:</div><ul class=\"examples\"><li><em>The new computer system knocks spots off the old one.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>knock on wood</strong> <em>American English</em> used to say that you hope your good luck so far will not change SYN touch wood<em>British English</em></div><div class=\"sense\"><span class=\"snum\">21</span> <strong>knock it off</strong> <em>spoken</em> used to tell someone to stop doing something, because it is annoying you</div><div class=\"sense\"><span class=\"snum\">22</span> <strong>[make a noise]</strong> <span class=\"gram\">[intransitive]</span> if an engine or pipes etc are knocking, they make a noise like something hard being hit, usually because something is wrong with them</div><div class=\"sense\"><span class=\"snum\">23</span> <strong>[heart]</strong> <span class=\"gram\">[intransitive]</span> if your heart is knocking, it is beating hard, especially because you are afraid <em>SYN pound</em></div><div class=\"sense\"><span class=\"snum\">24</span> <strong>I’ll knock your head/block off</strong> <em>spoken</em> used when threatening to hit someone very hard:</div><ul class=\"examples\"><li><em>If you say that again, I’ll knock your head off!</em></li></ul><div class=\"sense\"><span class=\"snum\">25</span> <strong>knock the bottom out of something</strong> <em>informal</em> to make something such as a market or industry fail suddenly:</div><ul class=\"examples\"><li><em>A sudden drop in supplies of certain chemicals could knock the bottom out of the engineering industry.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> the sound of something hard hitting a hard surface:</div><ul class=\"examples\"><li><em>a loud knock at the door</em></li><li><em>a knock in the engine</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> the action of something hard hitting your body:</div><ul class=\"examples\"><li><em>He got a knock on the head when he fell.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>take a knock</strong> <em>informal</em> to have some bad luck or trouble:</div><ul class=\"examples\"><li><em>Clive’s taken quite a few hard knocks lately.</em></li></ul></div></div>","3925":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /nɒt $ nɑːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[string/rope etc]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a part where one or more pieces of string, rope, cloth etc have been tied or twisted together:</div><ul class=\"examples\"><li><em>Are you any good at tying knots?</em></li><li><em>Thread the string through the hoop and tie it in a knot.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a part where hair, a thread etc has become accidentally twisted together:</div><ul class=\"examples\"><li><em>I can’t get the knots out of my hair.</em></li><li><strong><em>knot in</strong>: There’s a knot in my shoelace.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[hair style]</strong> a hair style in which your hair is arranged in a tight round shape on top of your head</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>[wood]</strong> a hard round place in a piece of wood where a branch once joined the tree</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[ship’s or aircraft&#x27;s speed]</strong> a unit for measuring the speed of ships and aircraft, equal to about 1,853 metres per hour</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[people]</strong> a small group of people standing close together</div><ul class=\"examples\"><li><strong><em>knot of</strong>: Knots of delegates stood around outside the conference centre.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[feeling]</strong> a tight uncomfortable feeling caused by a strong emotion such as fear or anger</div><ul class=\"examples\"><li><strong><em>knot of</strong>: a knot of anxiety in her stomach</em></li><li><em>Her stomach was in knots.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[hard mass]</strong> a tight painful place in a muscle</div></div>","3926":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /nəʊ $ noʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense knew /njuː $ nuː/, past participle known /nəʊn $ noʊn/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[have information]</strong> <span class=\"gram\">[intransitive, transitive]</span> to have information about something: GRAMMARIn more formal English, you say it is known that or it is known who/why/what etc: · It is known that the drug causes infertility.· It is not known how many people were killed.</div><ul class=\"examples\"><li><em>Who knows the answer?</em></li><li><em>There are instructions telling you everything you need to know.</em></li><li><em>Didn’t you know that?</em></li><li><strong><em>know what/how/where etc</strong>: Do you know what time it is? / I don’t know where to go.</em></li><li><strong><em>know (something/nothing etc) about something</strong>: I need to know more about the job before I decide whether to apply for it. / Little is known about the author’s childhood. / I know all about David and what he’s been up to!</em></li><li><strong><em>know (something/nothing etc) of something</strong>: I wonder if he knew of the plan? / Do you know of any good restaurants in the area? / You know nothing of this business.</em></li><li><strong><em>know (that)</strong>: We know that greenhouse gases can affect the climate.</em></li><li><em>Let me know (=tell me) what time you’re planning to arrive.</em></li><li><em>I thought you’d want to know immediately.</em></li><li><em>If you must know, I was with James last night (=used when you are angry because someone wants to know something).</em></li><li><strong><em>without somebody/somebody’s knowing</strong>: He slipped out of the house without his parents knowing (=secretly).</em></li><li><em>How did he know (=how did he find information about) our names?</em></li><li><strong><em>as you/we know</strong>: ‘I’m divorced, as you know,’ she said briefly.</em></li><li><strong><em>be known to do something</strong>: Smoking is known to increase a person’s risk of developing lung cancer.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[be sure]</strong> <span class=\"gram\">[intransitive, transitive]</span> to be sure about something: ► see thesaurus at sure</div><ul class=\"examples\"><li><em>‘Are you seeing Jim tomorrow?’ ‘I don’t know yet.’</em></li><li><strong><em>know (that)</strong>: I know I won’t get the job. / Ruth knew that she couldn’t continue in the relationship for much longer.</em></li><li><strong><em>know what/why/how etc</strong>: I know exactly what you need!</em></li><li><strong><em>know if/whether</strong>: The boy stared at him uncertainly, not knowing whether to believe him. / I don’t know if I’ll be able to come.</em></li><li><strong><em>knowing (that)</strong>: She forced herself to go out, knowing that she would feel more depressed if she stayed at home.</em></li><li><em>How do you know (=what makes you sure) he won’t do it again?</em></li><li><strong><em>know somebody/something to be something</strong>: It’s a story that I know to be true.</em></li><li><em>I think he’s still living in Chicago, but I don’t know for sure.</em></li><li><em>As far as I know, they’re arriving on Saturday (=used when you think something is true but are not sure).</em></li><li><em>I doubt I’ll win, but you never know (=used when you cannot be sure about something, but something good might happen).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[be familiar with somebody/something]</strong> <span class=\"gram\">[transitive]</span> to be familiar with a person, place etc:</div><ul class=\"examples\"><li><em>I’ve known her for twenty years.</em></li><li><em>Are you really thinking of leaving Kevin for a guy you barely know?</em></li><li><em>Do you know the nightclub on the corner of Maine Street?</em></li><li><em>I don’t know him very well.</em></li><li><em>We’re still getting to know each other really.</em></li><li><strong><em>know somebody from something</strong>: I know her from school.</em></li><li><strong><em>know somebody as something</strong>: Many people knew him as a local businessman.</em></li><li><em>Hepburn is best known for (=people are most likely to be familiar with) her roles in classic films such as ‘My Fair Lady’.</em></li><li><em>The museum outlines the development of the city as we know it today.</em></li><li><em>Does he know the way to your house (=know how to get there)?</em></li><li><em>I grew up here; I know the place like the back of my hand (=I know it very well).</em></li><li><em>I only know her by sight (=I often see her but have not really spoken to her).</em></li><li><em>She didn’t know me from Adam (=she did not know me at all), but she was really helpful.</em></li><li><strong><em>knowing somebody/if I know somebody</strong> (=used to say that you expect someone to behave in a particular way because you know them well): Knowing Sumi, my note’s probably still in her pocket. / He’ll be chatting up the women, if I know Ron!</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[realize]</strong> <span class=\"gram\">[intransitive, transitive]</span> to realize, find out about, or understand something:</div><ul class=\"examples\"><li><em>She knew the risks involved.</em></li><li><em>Hardly knowing what he was doing, Nick pulled out a cigarette.</em></li><li><strong><em>know (that)</strong>: Suddenly she knew that something was terribly wrong.</em></li><li><strong><em>know how/what/why etc</strong>: I didn’t know how difficult it would be.</em></li><li><strong><em>know to do something</strong>: She knows not to tell anyone.</em></li><li><strong><em>(do you) know what I mean?</strong> (=used to ask if someone understands or has the same feeling as you): It’s nice to have a change sometimes. Know what I mean?</em></li><li><strong><em>if you know what I mean</strong>: Sometimes it’s better not to ask too many questions, if you know what I mean.</em></li><li><em>‘I just felt so tired.’ ‘Yeah, I know what you mean.’ (=I understand, because I have had the same experience)</em></li><li><em>I should have known it wouldn’t be easy.</em></li><li><em>I might have known (=I am annoyed but not surprised) you would take that attitude.</em></li><li><strong><em>know exactly/precisely</strong>: I know exactly how you feel.</em></li><li><strong><em>know perfectly well/full well/only too well</strong>: He knew full well that what he was doing was dangerous.</em></li><li><strong><em>somebody will never know/no one will ever know</strong>: Just take it. No one will ever know.</em></li><li><em>‘That’s not what I mean, and you know it,’ he protested.</em></li><li><strong><em>if I had known/if I’d have known</strong>: I wouldn’t have come if I’d known you were so busy.</em></li><li><em>Little did she know (=she did not know) that years later she would have her own pool and luxury apartment in Florida.</em></li><li><em>She knew nothing of what had happened earlier that day.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[skill/experience]</strong> <span class=\"gram\">[transitive]</span> to have learned a lot about something or be skilful and experienced at doing something:</div><ul class=\"examples\"><li><em>I don’t know enough history to make a comparison.</em></li><li><em>I taught him everything he knows.</em></li><li><em>I know some French.</em></li><li><strong><em>know how to do something</strong>: Do you know how to change a fuse?</em></li><li><strong><em>know about</strong>: I have a friend who knows about antiques. / Bessie knew nothing about football.</em></li><li><em>Politicians know all about the power of language.</em></li><li><em>I don’t know the first thing about (=I know nothing about) looking after children.</em></li><li><em>I don’t really know what I’m doing (=I do not have enough skill and experience to deal with something) when it comes to cars.</em></li><li><em>The staff are dedicated people who clearly know what they are talking about.</em></li><li><em>She knew from experience that exams made her very nervous.</em></li><li><strong><em>know your job/subject/stuff</strong> (=be good at and know all you should about a job or subject)</em></li><li><em>a decent manager who knows the ropes (=has a lot of experience)</em></li><li><em>My cousin knows a thing or two (=knows a lot) about golf.</em></li><li><strong><em>know a song/tune/poem etc</strong> (=be able to sing a song, play a tune, say a poem etc because you have learned it): Do you know all the words to ‘As Time Goes By’?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[know somebody’s qualities]</strong> <span class=\"gram\">[transitive]</span> to think that someone has particular qualities</div><ul class=\"examples\"><li><strong><em>know somebody as something</strong>: I knew him as a hard-working, modest, and honest politician.</em></li><li><strong><em>know somebody for something</strong>: In fact, I knew her for a tough-minded young woman.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>know better</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to be wise or experienced enough not to do something:</div><ul class=\"examples\"><li><em>It’s just prejudice from educated people who should know better.</em></li><li><em>Eva knew better than to interrupt one of Mark’s jokes.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to know or think you know more than someone else:</div><ul class=\"examples\"><li><em>Everyone thought it was an accident. Only Dan knew better.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>not know any better</strong> used to say that someone does something bad or stupid because they have not been told or taught that it is wrong:</div><ul class=\"examples\"><li><em>Drugs are being sold to children who don’t know any better.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>know something inside out</strong> (also know something backwards<em>British English</em>, know something backwards and forwards<em>American English</em>) to be very familiar with something, especially because you have learned about it or because you have a lot of experience:</div><ul class=\"examples\"><li><em>Erikson knows the game inside out.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>know your way around something</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to be so familiar with something that you are confident and good at using it:</div><ul class=\"examples\"><li><em>She knows her way around a wine list.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to be familiar with a place so that you know where things are:</div><ul class=\"examples\"><li><em>I don’t know my way around the city yet.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>make yourself known (to somebody)</strong> <em>formal</em> to introduce yourself to someone:</div><ul class=\"examples\"><li><em>After she had gone, Paul made himself known to Dr Heatherton.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[recognize]</strong> <span class=\"gram\">[transitive]</span> to be able to recognize someone or something: ► see thesaurus at recognize</div><ul class=\"examples\"><li><em>Honestly, it had been so long, I hardly knew her.</em></li><li><strong><em>know somebody/something by something</strong>: He looked very different, but I knew him by his voice.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>know somebody/something as something</strong> to have a particular name:</div><ul class=\"examples\"><li><em>The main street between the castle and the palace is known as ‘the Royal Mile’.</em></li><li><em>Nitrous oxide is commonly known as laughing gas.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>know something from something</strong> to understand the difference between one thing and another:</div><ul class=\"examples\"><li><em>Lloyd doesn’t even know his right from his left.</em></li><li><em>At what age do children start to know right from wrong?</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>[experience]</strong> <span class=\"gram\">[transitive]</span> to have experience of a particular feeling or situation:</div><ul class=\"examples\"><li><em>I don’t think he ever knew true happiness.</em></li><li><strong><em>know about</strong>: I know all about being poor.</em></li><li><em>I’ve never known (=have never experienced) this to happen in all the time I’ve worked here.</em></li><li><em>I’ve never known him to shout (=he never shouts).</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>somebody/something is not known to be something</strong> or somebody/something has never been known to do something used to say there is no information that someone or something has particular qualities:</div><ul class=\"examples\"><li><em>This species is not known to be vicious.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>I’ve known somebody/something to do something</strong> or somebody/something has been known to do something used to say that someone does something sometimes or that something happens sometimes, even if it is unusual:</div><ul class=\"examples\"><li><em>People have been known to drive 500 miles just to visit the shop.</em></li><li><em>This type of fish has been known to live for 10 years or more.</em></li></ul><div class=\"sense\"><span class=\"snum\">40</span> <strong>there’s no knowing</strong> it is impossible to know:</div><ul class=\"examples\"><li><em>There was no knowing who might have read the letter.</em></li></ul><div class=\"sense\"><span class=\"snum\">41</span> <strong>let it be known/make it known (that)</strong> <em>formal</em> to make sure that people know something, especially by getting someone else to tell them:</div><ul class=\"examples\"><li><em>Farrar let it be known that he saw nothing wrong with the proposed solutions.</em></li></ul><div class=\"sense\"><span class=\"snum\">42</span> <strong>not want to know</strong> <em>British English</em> <em>informal</em> to not be interested in someone and what they want to say:</div><ul class=\"examples\"><li><em>She’d approached several model agencies but they just didn’t want to know.</em></li></ul><div class=\"sense\"><span class=\"snum\">43</span> <strong>know the score</strong> <em>informal</em> to understand a situation and all the good and bad features about it:</div><ul class=\"examples\"><li><em>I knew the score before I started the job.</em></li></ul><div class=\"sense\"><span class=\"snum\">44</span> <strong>not know what hit you</strong> <em>informal</em> to feel shocked and confused because something happens when you are not expecting it to:</div><ul class=\"examples\"><li><em>Poor man – I don’t think he knew what hit him.</em></li></ul><div class=\"sense\"><span class=\"snum\">45</span> <strong>know your place</strong> used to say that someone understands that they are less important than other people – usually used humorously:</div><ul class=\"examples\"><li><em>I know my place. I’ll get back to the kitchen!</em></li></ul><div class=\"sense\"><span class=\"snum\">46</span> <strong>know no bounds</strong> <em>formal</em> if a feeling or quality knows no bounds, it is not limited in any way:</div><ul class=\"examples\"><li><em>His enthusiasm knew no bounds.</em></li></ul><div class=\"sense\"><span class=\"snum\">47</span> <strong>somebody knows best</strong> used to say that someone should be obeyed or that their way of doing things should be accepted because they are experienced:</div><ul class=\"examples\"><li><em>She always thinks she knows best.</em></li><li><em>I have always hated the attitude that ‘the doctor knows best’.</em></li></ul><div class=\"sense\"><span class=\"snum\">48</span> <strong>before you know it</strong> used to say that something happens very quickly and when you are not expecting it:</div><ul class=\"examples\"><li><em>You’ll be home before you know it.</em></li></ul><div class=\"sense\"><span class=\"snum\">49</span> <strong>know different/otherwise</strong> <em>informal</em> to know that the opposite of something is true:</div><ul class=\"examples\"><li><em>He told people he didn’t care about her, but deep down he knew different.</em></li></ul><div class=\"sense\"><span class=\"snum\">50</span> <strong>know your own mind</strong> to be confident and have firm ideas about what you want and like</div><div class=\"sense\"><span class=\"snum\">51</span> <strong>you will be delighted/pleased etc to know (that)</strong> <em>formal</em> used before you give someone information that they will be pleased to hear:</div><ul class=\"examples\"><li><em>You will be pleased to know that we have accepted your offer.</em></li></ul><div class=\"sense\"><span class=\"snum\">52</span> <strong>it’s..., Jim, but not as we know it</strong> <em>informal humorous</em> used to say that something is completely different from what we would normally expect something of its type to be:</div><ul class=\"examples\"><li><em>It’s the blues, Jim, but not as we know it.</em></li></ul></div>","3927":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> knowl‧edge</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈnɒlɪdʒ $ ˈnɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the information, skills, and understanding that you have gained through learning or experience RegisterIn everyday English, people usually say that someone knows about something rather than has knowledge of/about something:· He didn’t know much about American history.</div><ul class=\"examples\"><li><strong><em>knowledge of</strong>: He did not have much knowledge of American history.</em></li><li><strong><em>knowledge about</strong>: the need to increase knowledge about birth control</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> when you know about a particular situation or event, or the information you have about it:</div><ul class=\"examples\"><li><em>Evans denied all knowledge of the robbery.</em></li><li><em>I had no knowledge of this whatsoever until ‘The Times’ contacted me.</em></li><li><strong><em>(secure/safe) in the knowledge that</strong>: Kay smiled, secure in the knowledge that she was right.</em></li><li><strong><em>be common/public knowledge</strong> (=be known about by everyone): Their affair is public knowledge.</em></li><li><strong><em>to (the best of) somebody’s knowledge</strong> (=used to say that someone may not know the true facts): To the best of my knowledge, the new project will be starting in June. / To our knowledge, this is the first time it’s happened. / ‘Is it true that she’s leaving the company?’ ‘Not to my knowledge (=I do not think so).’</em></li><li><strong><em>without somebody’s knowledge</strong>: He was annoyed to find the contract had been signed without his knowledge.</em></li><li><em>She acted with the full knowledge of her boss (=her boss knew about her action).</em></li><li><em>Ministers publicly denied that they had prior knowledge of the attack (=they denied that they knew that it was going to happen).</em></li></ul></div>","3928":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[only before noun]</span> used about something that people know about or have discovered:</div><ul class=\"examples\"><li><em>a study of all the known facts</em></li><li><em>her last known address</em></li><li><em>Apart from vaccines, there is no known way to protect against meningitis.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[only before noun]</span> a known criminal, drug dealer etc is someone who people know to be regularly involved in criminal activities or to do other things that are disapproved of:</div><ul class=\"examples\"><li><em>He was found with several other known sex offenders.</em></li><li><em>a known liar</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be known for something</strong> to be famous or known about by a lot of people because of something:</div><ul class=\"examples\"><li><em>He’s known for his good looks.</em></li><li><em>The region is known for its fine wines.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>well-known/little-known/lesser-known</strong> used when saying how famous someone is:</div><ul class=\"examples\"><li><em>works by lesser-known French artists</em></li></ul></div>"};